/* Compact world context in the scene, full named route only in the atlas. */
const WorldMap=(()=>{
    const route=r=>MageRealms.routes[r],current=()=>RealmProgression.enabled()?RealmProgression.current():MageRealms.place(state.realm,state.levels[state.realm]);
    function location(){if(RealmProgression.enabled())return RealmProgression.location();return `<button class="location-plaque" data-action="map" aria-label="${realms[state.realm]} realm, ${current().name}. Open realm map"><span class="kicker">${realms[state.realm]} realm</span><strong>${current().name}</strong><span class="location-route" aria-hidden="true">${route(state.realm).places.map((_,i)=>`<i class="${state.cleared[state.realm]>i||state.won[state.realm]?'done':''} ${state.levels[state.realm]===i+1?'here':''}"></i>`).join('')}${sprite('golem')}<span>⌄</span></span></button>`;}
    function progress(){if(RealmProgression.enabled())return RealmProgression.progress();return `<div class="place-progress" role="progressbar" aria-label="Clearing ${current().name}" aria-valuemin="0" aria-valuemax="3" aria-valuenow="${Math.min(state.stageKills,3)}"><i style="width:${gate()||state.won[state.realm]?100:Math.min(1,state.stageKills/3)*100}%"></i></div>`;}
    function refresh(){if(RealmProgression.enabled())return RealmProgression.refresh();const el=phone.querySelector('.realm-location');if(!el)return;const sample=document.createElement('div');sample.innerHTML=location();const old=el.querySelector('.location-plaque'),next=sample.firstElementChild;old.setAttribute('aria-label',next.getAttribute('aria-label'));old.querySelector('.kicker').textContent=next.querySelector('.kicker').textContent;old.querySelector('strong').textContent=next.querySelector('strong').textContent;old.querySelector('.location-route').innerHTML=next.querySelector('.location-route').innerHTML;const progress=el.querySelector('.place-progress');progress.setAttribute('aria-label','Clearing '+current().name);progress.setAttribute('aria-valuenow',Math.min(state.stageKills,3));progress.firstElementChild.style.width=(gate()||state.won[state.realm]?100:Math.min(1,state.stageKills/3)*100)+'%';}
    const points=n=>Array.from({length:n},(_,i)=>({x:i%2===0?24:76,y:13+i/(n-1)*73}));
    function view(){if(RealmProgression.enabled())return RealmMapStudy.enabled()?RealmMapStudy.view():RealmProgression.view();
        const r=state.modal.realm??state.realm,path=route(r),open=canVisit(r),positions=points(path.places.length+1),cleared=state.cleared[r],won=state.won[r];
        return `<div class="atlas-tabs" role="group" aria-label="Choose realm to view">${realms.map((name,i)=>`<button data-map-realm="${i}" aria-pressed="${i===r}" aria-label="${name} realm${canVisit(i)?'':', locked'}">${ui(name.toLowerCase())}<span>${name}</span>${canVisit(i)?'':ui('lock','inline-icon')}</button>`).join('')}</div><div class="atlas-title"><strong>${path.name} realm</strong><span>${metric(path.name.toLowerCase(),'Shards',path.name+' shard farming')}${won?'<span class="status-chip">Conquered</span>':''}${RealmDiscoveries.trigger(r,true)}</span></div><div class="realm-atlas realm-${path.name.toLowerCase()}">${`<div class="atlas-terrain scenery ${r===1?'ice':''}" style="--realm-x:${({0:0,2:50,3:100})[r]||0}%"></div>`}<svg class="atlas-path" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${positions.slice(1).map((p,i)=>`<path class="${cleared>i||won?'done':''}" d="M ${positions[i].x} ${positions[i].y} L ${p.x} ${p.y}"/>`).join('')}</svg>${path.places.map((p,i)=>{const enabled=MageRealms.canTravel(state,r,i+1),here=state.realm===r&&state.levels[r]===i+1;return `<button class="atlas-place ${here?'here':''} ${cleared>i||won?'cleared':''}" data-location="${i+1}" data-location-realm="${r}" style="--px:${positions[i].x};--py:${positions[i].y}" ${enabled?'':'disabled'} ${here?'aria-current="location"':''} aria-label="${p.name}${here?', farming here':enabled?', travel here':', locked'}"><span class="atlas-landmark">${sprite(p.art)}${here?'<span class="map-you">●</span>':cleared>i||won?'<span class="map-check">✓</span>':!enabled?ui('lock','map-lock'):''}</span><strong>${p.name}</strong></button>`}).join('')}<button class="atlas-place atlas-boss ${MageRealms.gate(state,r)?'ready':''} ${won?'defeated':''}" data-map-boss="${r}" style="--px:${positions.at(-1).x};--py:${positions.at(-1).y}" ${!open||(!won&&cleared<path.places.length)?'disabled':''} aria-label="${path.boss.name}, ${won?'guardian defeated':cleared>=path.places.length?'boss ready':'clear the route first'}"><span class="atlas-landmark">${sprite('golem')}${won?'<span class="map-check">✓</span>':''}</span><strong>${path.boss.name}</strong><small>${won?'Defeated':'Boss'}</small></button></div><div class="atlas-footer">${!open?`<span>${ui('lock','inline-icon')} Defeat the ${realms[r-1]} guardian</span>`:`<span><i class="map-current-key"></i> Farming here</span><span>${glyph('check')} Cleared</span>`}</div>`;
    }
    function refreshAtlas(){if(RealmProgression.enabled())return RealmMapStudy.enabled()?RealmMapStudy.refreshAtlas():RealmProgression.refreshAtlas();
        const atlas=phone.querySelector('.realm-atlas');if(!atlas)return;
        const next=document.createElement('div');next.innerHTML=view();
        for(const button of atlas.querySelectorAll('.atlas-place')){
            const selector=button.dataset.location?'[data-location="'+button.dataset.location+'"]':'[data-map-boss]';
            const fresh=next.querySelector(selector);button.className=fresh.className;button.disabled=fresh.disabled;button.setAttribute('aria-label',fresh.getAttribute('aria-label'));
            if(fresh.hasAttribute('aria-current'))button.setAttribute('aria-current',fresh.getAttribute('aria-current'));else button.removeAttribute('aria-current');
            button.innerHTML=fresh.innerHTML;
        }
        atlas.querySelector('.atlas-path').innerHTML=next.querySelector('.atlas-path').innerHTML;
    }
    function travel(r,level){if(!MageRealms.travel(state,r,level))return;resetIdleAnimation();go('realm');}
    function boss(r){if(!canVisit(r))return;if(!MageRealms.travel(state,r,MageRealms.count(r)))return;resetIdleAnimation();go('boss');}
    function returned(r){const realm=r.realm??state.realm,end=Math.min(MageRealms.count(realm),r.end||MageRealms.count(realm)),from=MageRealms.place(realm,r.startLevel||1);return `<div class="return-destination">${sprite('portal')}<div><span class="kicker">${realms[realm]} realm</span><span>${from.name} ${glyph('arrow')}</span><strong>${MageRealms.place(realm,end).name}</strong></div><span class="status-chip">Boss waiting</span></div>`;}
    return {location,progress,refresh,refreshAtlas,view,travel,boss,returned,current};
})();
